// Confirmed scalar elementary audio, projected without re-encoding.
// GPL-3.0-or-later. All physical reads go through ResourceSource/SHA-256.
#pragma once
#include "progressiveresourceio.h"

namespace foxicmp { namespace progressive {
template<class Profile> class RawAudioBridge {
    using Waiting=typename Profile::Waiting;
    struct Published {Snapshot model;std::string resource,track;uint64_t prefix=0;bool complete=false;typename Profile::Layout layout;harvester::Snapshot legacy;};
    std::shared_ptr<ResourceSource> source;std::filesystem::path registry;std::shared_ptr<const Published> current;std::mutex publication;
    std::atomic<bool> cancelled{false},failed{false};std::atomic<uint64_t> decoderBytes{0};
    static void supported(bool ok,const char* why){Require(ok,Profile::Tag(),why,"unsupported_media");}
    static std::shared_ptr<Published> plan(const std::string& json){auto p=std::make_shared<Published>();p->model=Parse(json);const auto& m=p->model;
        rapidjson::Document d;d.Parse(json.c_str());supported(!d.HasMember("segmentCatalog"),Profile::Message("Raw FLAC has no segment catalog").c_str());
        supported(m.tracks.size()==1 && m.resources.size()==1 && !m.live && !m.hasWindow && m.knownDuration && m.duration>0 && m.numerator==1 && m.denominator==10000000 && m.offset==0,Profile::Message("Raw FLAC requires one VOD audio track/resource, known duration and zero offset").c_str());
        const auto& t=m.tracks.begin()->second;supported(t.kind=="audio" && t.required && t.container==Profile::Hint() && t.codec==Profile::Codec() && !t.resource.empty() && t.initialization.empty() && t.segments.empty(),Profile::Message("Raw FLAC requires one explicit required scalar FLAC audio track").c_str());p->track=t.id;p->resource=t.resource;const auto& r=m.resources.at(t.resource);
        supported(!r.retired,Profile::Message("Retired raw FLAC resource").c_str());Require(r.integrity,Profile::Tag(),Profile::Message("Raw FLAC requires SHA-256").c_str(),"integrity-required");for(const auto& range:r.ranges){supported(range.offset==p->prefix,Profile::Message("Raw FLAC requires a contiguous confirmed prefix").c_str());p->prefix+=range.length;}
        Require(m.state!="failed" && m.state!="cancelled" && t.state!="failed" && t.state!="cancelled" && r.state!="failed" && r.state!="cancelled",Profile::Tag(),Profile::Message("Raw FLAC writer/resource failed").c_str(),"resource-failed");
        p->complete=m.state=="complete" && t.state=="complete" && r.state=="complete" && r.known && p->prefix==r.length;return p;}
    void check()const{Require(!cancelled.load(),Profile::Tag(),"Reader cancelled","cancelled");Require(!failed.load(),Profile::Tag(),Profile::Message("Raw FLAC source failed; close and reopen").c_str(),"session_closed");}
    bool exact(const std::string& id,uint64_t at,void* data,size_t count){auto* p=static_cast<char*>(data);for(size_t n=0;n<count;){check();const auto k=(std::min)(size_t(65536),count-n);auto r=source->read(id,at+n,p+n,k);Require(r.data() && r.bytes==k,Profile::Tag(),r.reason.c_str(),r.data()?"source-truncated":r.code.c_str());n+=k;}return true;}
    void materialize(Published& p,const Published* old){if(old)p.layout=old->layout;Require(p.model.tracks.at(p.track).initializationReady,Profile::Tag(),Profile::Message("Wait for raw FLAC initialization").c_str(),"waiting_initialization");
        p.layout.Update([&](uint64_t at,void* data,size_t n){return exact(p.resource,at,data,n);},p.prefix,p.complete);
        const auto& info=p.layout.info;const auto ticks=[&](uint64_t n){return int64_t(n/info.rate*10000000+(n%info.rate)*10000000/info.rate);};
        supported(!info.total || std::abs(ticks(info.total)-p.model.duration)<=1,Profile::Message("Raw FLAC STREAMINFO duration disagrees with session").c_str());supported(ticks(p.layout.Samples())<=p.model.duration,Profile::Message("Raw FLAC frames exceed session duration").c_str());if(p.complete)supported(std::abs(ticks(p.layout.Samples())-p.model.duration)<=1,Profile::Message("Raw FLAC complete duration mismatch").c_str());
        auto& out=p.legacy;out.sessionId=p.model.id;out.generation=p.model.generation;out.revision=p.model.revision;out.duration=p.model.duration;out.state=p.complete?harvester::State::Complete:p.model.state=="paused"?harvester::State::Paused:harvester::State::Downloading;out.tracks.resize(1);auto& t=out.tracks[0];t.path=Profile::Path();t.container="m4a";t.audio=true;t.required=true;t.fragmented=true;t.initializationReady=p.layout.Initialized();t.available=p.layout.view.bytes;t.total=p.complete?t.available:0;t.state=p.complete?harvester::State::Complete:out.state;}
    void cleanup()noexcept{if(!source)return;try{auto ids=source->readerIds();source.reset();for(const auto& id:ids)ReaderRequest(registry,"{\"version\":1,\"action\":\"readerForget\",\"readerId\":\""+id+"\"}");}catch(...){source.reset();}}
public:
    static bool Declared(const std::string& json){rapidjson::Document d;d.Parse(json.c_str());if(!d.IsObject() || !d.HasMember("tracks") || !d["tracks"].IsArray())return false;for(const auto& t:d["tracks"].GetArray())if(t.IsObject() && t.HasMember("containerHint") && t["containerHint"].IsString() && std::string(t["containerHint"].GetString())==Profile::Hint())return true;return false;}
    static void CheckProfile(const std::string& json){plan(json);}
    RawAudioBridge(const std::filesystem::path& root,const std::filesystem::path& receipts,const std::string& json):registry(receipts){auto p=plan(json);supported(p->prefix<=16777216,Profile::Message("Raw FLAC initial prefix exceeds 16 MiB").c_str());source=std::make_shared<ResourceSource>(root,receipts,json);try{materialize(*p,nullptr);current=std::move(p);}catch(const Waiting&){cleanup();throw Error("waiting_initialization",Profile::Tag(),Profile::Message("Wait for complete native FLAC metadata").c_str());}catch(const Error&){cleanup();throw;}catch(const std::exception& e){cleanup();throw Error("unsupported_media",Profile::Tag(),e.what());}}
    ~RawAudioBridge(){cancel();cleanup();}
    harvester::Snapshot snapshot()const{return std::atomic_load(&current)->legacy;}
    std::vector<BoundResource> bindings()const{auto p=std::atomic_load(&current);return {source->binding(p->resource)};}
    bool readIndex(unsigned k,uint64_t at,void* data,size_t count){try{check();supported(k==0,Profile::Message("Raw FLAC has one track").c_str());auto p=std::atomic_load(&current);return p->layout.ReadAt([&](uint64_t off,void* out,size_t n){return exact(p->resource,off,out,n);},at,data,count);}catch(...){failed.store(true);return false;}}
    int64_t readPayload(unsigned k,uint64_t at,void* data,size_t count){try{check();supported(k==0 && count<=65536 && (data || !count),Profile::Message("Invalid raw FLAC view read").c_str());auto p=std::atomic_load(&current);const auto size=p->layout.view.bytes;if(!count)return 0;if(at>=size)return p->complete && at==size?0:-1;const auto n=size_t((std::min)(uint64_t(count),size-at));std::vector<uint8_t> bytes(n);supported(readIndex(k,at,bytes.data(),n),Profile::Message("Raw FLAC virtual read failed").c_str());std::memcpy(data,bytes.data(),n);decoderBytes.fetch_add(n);return int64_t(n);}catch(...){failed.store(true);return -1;}}
    void publish(const std::string& json){std::lock_guard<std::mutex> lock(publication);check();auto old=std::atomic_load(&current);auto p=plan(json);Advance(old->model,p->model);supported(p->prefix-old->prefix<=16777216,Profile::Message("Append at most 16 MiB of raw FLAC").c_str());try{source->publish(json);materialize(*p,old.get());std::shared_ptr<const Published> accepted=std::move(p);std::atomic_store(&current,std::move(accepted));}catch(const Error&){failed.store(true);throw;}catch(const std::exception& e){failed.store(true);throw Error("unsupported_media",Profile::Tag(),e.what());}}
    void verify(){check();try{source->verifyPinned();}catch(...){failed.store(true);throw;}}
    void cancel(){cancelled.store(true);if(source)source->cancel();}
    std::string details()const{auto p=std::atomic_load(&current);rapidjson::Document d;d.SetObject();auto& a=d.GetAllocator();d.AddMember("schemaVersion",2,a);d.AddMember("generation",Value(std::to_string(p->model.generation).c_str(),a),a);d.AddMember("revision",Value(std::to_string(p->model.revision).c_str(),a),a);d.AddMember("writerInstanceId",Value(p->model.writer.c_str(),a),a);d.AddMember("mediaMode",Value(Profile::Mode(),a),a);d.AddMember("singleTrack",true,a);d.AddMember("segments",false,a);d.AddMember("physicalResources",1,a);d.AddMember("videoContainer","",a);d.AddMember("audioContainer",Value(Profile::Hint(),a),a);d.AddMember("decoderContainer","fmp4",a);d.AddMember("videoCodec","",a);d.AddMember("audioCodec",Value(Profile::Codec(),a),a);Value bytes(rapidjson::kObjectType);bytes.AddMember("video","0",a);bytes.AddMember("audio",Value(std::to_string(decoderBytes.load()).c_str(),a),a);d.AddMember("decoderIoBytes",bytes,a);
        if(!p->model.metadata.empty()){rapidjson::Document m;m.Parse(p->model.metadata.c_str());d.AddMember("metadata",Value(m,a),a);}const auto& track=p->model.tracks.at(p->track);Value tracks(rapidjson::kArrayType),t(rapidjson::kObjectType);t.AddMember("index",0,a);t.AddMember("id",Value(track.id.c_str(),a),a);t.AddMember("kind","audio",a);t.AddMember("codec",Value(Profile::Codec(),a),a);t.AddMember("container",Value(Profile::Hint(),a),a);t.AddMember("required",true,a);t.AddMember("default",true,a);t.AddMember("ready",true,a);t.AddMember("state","ready",a);t.AddMember("error","",a);t.AddMember("errorCode","",a);t.AddMember("label",Value(track.label.c_str(),a),a);t.AddMember("language",Value(track.language.c_str(),a),a);t.AddMember("decoderIoBytes",Value(std::to_string(decoderBytes.load()).c_str(),a),a);tracks.PushBack(t,a);d.AddMember("mediaTracks",tracks,a);d.AddMember("subtitleTracks",Value(rapidjson::kArrayType),a);Value frameKey(Profile::FramesKey(),a);d.AddMember(frameKey,uint32_t(p->layout.Frames()),a);return lease_detail::Encode(d);}
};
}} // namespace foxicmp::progressive
